const out = [];
for (const item of $input.all()) {
  const c = item.json;
  const batchType = (c.metadata && c.metadata.batch_type) ? c.metadata.batch_type : "unknown";
  out.push({ json: {
    batch_id: String(c.id || ''),
    batch_type: batchType,
    status: c.status || 'submitted',
    input_file_id: c.input_file_id || '',
    output_file_id: '',
    submitted_at: new Date().toISOString(),
    completed_at: ''
  }});
}
return out;

const rows = $json.rows || [];
const out = [];
for (const row of rows) {
  for (const slot of [1, 2, 3]) {
    const url = row['image_url_' + slot];
    if (url && String(url).trim()) {
      out.push({ json: { row_number: row.row_number, slot, url: String(url).trim(), retryCount: 0 } });
    }
  }
}
return out;

const originalRows = $('Prepare Chunk').first().json.rows || [];
const batchType = $('Prepare Chunk').first().json.batch_type;

const items = $input.all();
const imgMap = {};
for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const rn = item.json.row_number;
  const slot = item.json.slot;
  if (!item.binary || !item.binary.data) continue;
  if ((item.binary.data.bytes || 0) < 5000) continue;
  const mime = item.binary.data.mimeType || 'image/jpeg';
  const buffer = await this.helpers.getBinaryDataBuffer(i, 'data');
  const b64 = buffer.toString('base64');
  if (!imgMap[rn]) imgMap[rn] = {};
  imgMap[rn][slot] = 'data:' + mime + ';base64,' + b64;
}

const enrichedRows = originalRows.map(row => {
  const imgs = imgMap[row.row_number] || {};
  return Object.assign({}, row, {
    image_b64_1: imgs[1] || '',
    image_b64_2: imgs[2] || '',
    image_b64_3: imgs[3] || ''
  });
});

return [{ json: { batch_type: batchType, rows: enrichedRows } }];
